from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    # Step 1: Remove spaces from the input string
    paren_string = paren_string.replace(" ", "")

    # Step 2: Iterate through the input string and identify groups of nested parentheses
    groups = []
    current_group = ""
    for char in paren_string:
        if char == "(":
            current_group += char
        elif char == ")":
            current_group += char
            groups.append(current_group)
            current_group = ""

    # Step 3: Separate each group into distinct strings
    separated_groups = [group for group in groups]

    # Step 4: Ensure each group is balanced
    def is_balanced(group):
        stack = []
        for char in group:
            if char == "(":
                stack.append(char)
            elif char == ")":
                if not stack:
                    return False
                stack.pop()
        return len(stack) == 0

    balanced_groups = [group for group in separated_groups if is_balanced(group)]

    # Step 5: Return the separated groups as a list
    return balanced_groups

